import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {spawnAoeServe} from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/aoeServe.ts';
import {startAcpSession,postPrompt,replayFrames} from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/acp.ts';
const [binary]=process.argv.slice(2);assert(binary?.startsWith('/'),'absolute binary required');
process.env.AOE_E2E_BINARY=binary;
process.env.AOE_E2E_DEBUG='1';
const until=async(fn,label,ms=30000)=>{const deadline=Date.now()+ms;for(;;){const value=await fn();if(value)return value;if(Date.now()>=deadline)throw Error('deadline: '+label);await new Promise(resolve=>setTimeout(resolve,50));}};
let serve;
try {
 const started=await startAcpSession(async opts=>{serve=await spawnAoeServe({...opts,workerIndex:0,parallelIndex:22});return serve;},{
  title:'retained-target-load-before',
  fakeAcpScript:{failOn:{method:'session/load',code:-32603,message:'PRIVATE_NATIVE_LOAD_SERVICE_UNAVAILABLE'},turns:[{updates:[{sessionUpdate:'agent_message_chunk',content:{type:'text',text:'ORIGINAL_CONTEXT_OUTPUT'}}],stopReason:'end_turn'}]},
 });
 serve=started.serve;const id=started.sessionId;
 const frames=()=>replayFrames(serve.baseUrl,id);
 const row=async()=>{const body=await fetch(serve.baseUrl+'/api/sessions').then(r=>r.json());return (Array.isArray(body)?body:body.sessions).find(r=>r.id===id);};
 const nativeLog=()=>readFileSync(serve.home+'/fake-acp.log','utf8');
 const originalSid=await until(async()=>(await frames()).find(f=>f.event?.AcpSessionAssigned)?.event.AcpSessionAssigned.acp_session_id,'original conversation assignment');
 await until(async()=>(await row()).acp_session_id===originalSid,'original durable target');
 assert((await postPrompt(serve.baseUrl,id,'ORIGINAL_EXPLICIT_INPUT')).ok);
 await until(async()=>JSON.stringify(await frames()).includes('ORIGINAL_CONTEXT_OUTPUT'),'original turn output');
 await until(async()=>(await frames()).some(f=>f.event?.Stopped?.reason==='prompt_complete'),'original turn complete');
 const beforeFrames=await frames();const boundary=Math.max(...beforeFrames.map(f=>f.seq));
 const stopped=await fetch(serve.baseUrl+'/api/sessions/'+id+'/acp',{method:'DELETE'});
 assert.equal(stopped.status,204,'explicit stop completes before cold retry');
 assert.equal((await row()).acp_session_id,originalSid,'stop retains durable native conversation');
 const restarted=await fetch(serve.baseUrl+'/api/sessions/'+id+'/acp/spawn',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
 assert(restarted.ok,'explicit spawn accepted without fresh-selection field');
 const replacement=await until(async()=>(await frames()).find(f=>f.seq>boundary&&f.event?.AcpSessionAssigned?.acp_session_id!==undefined&&f.event.AcpSessionAssigned.acp_session_id!==originalSid),'baseline fresh substitution after generic load error');
 const replacementSid=replacement.event.AcpSessionAssigned.acp_session_id;
 await until(async()=>(await row()).acp_session_id===replacementSid,'replacement association persisted');
 const finalFrames=await frames();const log=nativeLog();
 const reset=finalFrames.find(f=>f.seq>boundary&&f.event?.SessionContextReset);
 assert(reset,'baseline emits context reset without explicit fresh choice');
 assert(log.includes('handleRequest method=session/load '),'cold retry attempted stored native target');
 assert.equal([...log.matchAll(/handleRequest method=session\/new id=/g)].length,2,'initial new plus implicit fresh after failed load');
 assert.equal([...log.matchAll(/handleRequest method=session\/prompt id=/g)].length,1,'no second prompt or replay was requested');
 assert(JSON.stringify(finalFrames).includes('ORIGINAL_CONTEXT_OUTPUT'),'event history remains distinct from native association replacement');
 console.log('BASELINE_ACP_LOAD_ERROR_SUBSTITUTES_FRESH',JSON.stringify({id,originalSid,replacementSid,loadError:'PRIVATE_NATIVE_LOAD_SERVICE_UNAVAILABLE',spawnHttp:restarted.status,newRequests:2,promptRequests:1,reset:reset.event,scope:'real AoE daemon/runner and fake native ACP; proves association replacement, not native history disappearance'}));
} finally {
 if(serve){await serve.stop();console.log('PRIVATE_LOAD_BASELINE_CLEANUP_GREEN');}
}
